class Counter {
  #count = 0; #mailbox = []; #draining = false;
  tell(msg) { this.#mailbox.push(msg); void this.#drain(); }   // never blocks the caller
  async #drain() {
    if (this.#draining) return; this.#draining = true;
    try { for (let m; (m = this.#mailbox.shift()); ) await this.#handle(m); }
    finally { this.#draining = false; }
  }
  async #handle(m) { if (m.type === 'add') this.#count += m.n; }
}
